function normalizeAppTemplate(html) {
  if (!html) return '';
  return String(html)
    .replace(/^\s*<!DOCTYPE[^>]*>/i, '')
    .replace(/^\s*<html[^>]*>/i, '')
    .replace(/<\/html>\s*$/i, '')
    .replace(/^\s*<head[^>]*>[\s\S]*?<\/head>\s*/i, '')
    .replace(/^\s*<body[^>]*>/i, '')
    .replace(/<\/body>\s*$/i, '')
    .replace(/^\s*<\/head>/i, '')
    .replace(/<\/head>\s*/gi, '')
    .replace(/<\/body>\s*/gi, '')
    .trim();
}
function mountAppShell() {
  if (__shellMounted) return;
  __shellMounted = true;
  let app = safeGetElement('app');
  if (!app) return;
  const shell = normalizeAppTemplate(APP_TEMPLATE);
  if (shell) {
    app.innerHTML = shell;
  }
}
